in highp vec3 in_POSITION0;
in mediump vec4 in_COLOR0;
in highp vec2 in_TEXCOORD0;
out mediump vec4 vs_COLOR0;
out highp vec2 vs_TEXCOORD0;
out highp vec2 vs_TEXCOORD1;
out highp vec4 vs_TEXCOORD3;
out highp vec2 vs_TEXCOORD4;
out highp vec2 vs_TEXCOORD5;
vec4 u_xlat0;
vec4 u_xlat1;
mediump vec4 u_xlat16_1;
mediump vec4 u_xlat16_2;
mediump vec3 u_xlat16_3;
vec3 u_xlat4;
bvec3 u_xlatb4;
bvec3 u_xlatb5;
bool u_xlatb18;
void main()
{
    u_xlat0.xyz = in_POSITION0.yyy * hlslcc_mtx4x4unity_ObjectToWorld[1].xyz;
    u_xlat0.xzw = hlslcc_mtx4x4unity_ObjectToWorld[0].xyz * in_POSITION0.xxx + u_xlat0.xyz;
    vs_TEXCOORD3.w = u_xlat0.y;
    u_xlat0.xyz = hlslcc_mtx4x4unity_ObjectToWorld[2].xyz * in_POSITION0.zzz + u_xlat0.xzw;
    u_xlat0.xyz = u_xlat0.xyz + hlslcc_mtx4x4unity_ObjectToWorld[3].xyz;
    u_xlat1 = u_xlat0.yyyy * hlslcc_mtx4x4unity_MatrixVP[1];
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[0] * u_xlat0.xxxx + u_xlat1;
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[2] * u_xlat0.zzzz + u_xlat1;
    vs_TEXCOORD3.xyz = u_xlat0.xyz;
    u_xlat0 = u_xlat1 + hlslcc_mtx4x4unity_MatrixVP[3];
    gl_Position = u_xlat0;
    u_xlat0.xyz = u_xlat0.xyw / u_xlat0.www;
    u_xlat16_2.xyz = in_COLOR0.xyz / in_COLOR0.www;
    u_xlat16_3.xyz = u_xlat16_2.xyz + vec3(0.0549999997, 0.0549999997, 0.0549999997);
    u_xlat16_3.xyz = u_xlat16_3.xyz * vec3(0.947867334, 0.947867334, 0.947867334);
    u_xlat1.xyz = log2(abs(u_xlat16_3.xyz));
    u_xlat1.xyz = u_xlat1.xyz * vec3(2.4000001, 2.4000001, 2.4000001);
    u_xlat1.xyz = exp2(u_xlat1.xyz);
    u_xlat16_3.xyz = u_xlat16_2.xyz * vec3(0.0773993805, 0.0773993805, 0.0773993805);
    u_xlatb4.xyz = greaterThanEqual(vec4(0.0404499993, 0.0404499993, 0.0404499993, 0.0), u_xlat16_2.xyzx).xyz;
    u_xlat16_2.x = (u_xlatb4.x) ? u_xlat16_3.x : u_xlat1.x;
    u_xlat16_2.y = (u_xlatb4.y) ? u_xlat16_3.y : u_xlat1.y;
    u_xlat16_2.z = (u_xlatb4.z) ? u_xlat16_3.z : u_xlat1.z;
    u_xlat16_1.xyz = u_xlat16_2.xyz * in_COLOR0.www;
    u_xlat16_2.xyz = in_COLOR0.xyz + vec3(0.0549999997, 0.0549999997, 0.0549999997);
    u_xlat16_2.xyz = u_xlat16_2.xyz * vec3(0.947867334, 0.947867334, 0.947867334);
    u_xlat4.xyz = log2(abs(u_xlat16_2.xyz));
    u_xlat4.xyz = u_xlat4.xyz * vec3(2.4000001, 2.4000001, 2.4000001);
    u_xlat4.xyz = exp2(u_xlat4.xyz);
    u_xlat16_2.xyz = in_COLOR0.xyz * vec3(0.0773993805, 0.0773993805, 0.0773993805);
    u_xlatb5.xyz = greaterThanEqual(vec4(0.0404499993, 0.0404499993, 0.0404499993, 0.0), in_COLOR0.xyzx).xyz;
    {
        vec4 hlslcc_movcTemp = u_xlat16_2;
        hlslcc_movcTemp.x = (u_xlatb5.x) ? u_xlat16_2.x : u_xlat4.x;
        hlslcc_movcTemp.y = (u_xlatb5.y) ? u_xlat16_2.y : u_xlat4.y;
        hlslcc_movcTemp.z = (u_xlatb5.z) ? u_xlat16_2.z : u_xlat4.z;
        u_xlat16_2 = hlslcc_movcTemp;
    }
    u_xlatb18 = in_COLOR0.w==0.0;
    u_xlat16_2.w = 0.0;
    u_xlat16_1.w = in_COLOR0.w;
    u_xlat16_1 = (bool(u_xlatb18)) ? u_xlat16_2 : u_xlat16_1;
    u_xlatb18 = u_xlat16_1.w==0.0;
    u_xlat16_2.xyz = u_xlat16_1.xyz / u_xlat16_1.www;
    vs_COLOR0.xyz = (bool(u_xlatb18)) ? u_xlat16_1.xyz : u_xlat16_2.xyz;
    vs_COLOR0.w = u_xlat16_1.w;
    u_xlat0.y = u_xlat0.y * _ProjectionParams.x;
    u_xlat0.xzw = u_xlat0.xzy * vec3(0.5, 0.5, 0.5);
    vs_TEXCOORD1.xy = u_xlat0.zz + u_xlat0.xw;
    vs_TEXCOORD0.xy = in_TEXCOORD0.xy;
    u_xlat0.xy = vec2(1.0, 1.0) / vec2(_BoundingBox.x, _BoundingBox.y);
    u_xlat0.xy = u_xlat0.xy * in_POSITION0.xy;
    vs_TEXCOORD5.xy = u_xlat0.xy * vec2(0.5, 1.0) + vec2(0.5, 0.0);
    vs_TEXCOORD4.xy = in_TEXCOORD0.xy * _IceNoiseTex_ST.xy + _IceNoiseTex_ST.zw;
    return;
}

#endif
