	UNITY_UNIFORM vec2                _BoundingBox;
	UNITY_UNIFORM mediump float Xhlslcc_UnusedX_LightAtten;
	UNITY_UNIFORM vec4 Xhlslcc_UnusedX_DistortionTex_MoveCenter;
	UNITY_UNIFORM vec4 Xhlslcc_UnusedX_DistortionTex_ST;
	UNITY_UNIFORM float Xhlslcc_UnusedX_DistortionTex_Rota;
