#if HLSLCC_ENABLE_UNIFORM_BUFFERS
};
#endif
UNITY_LOCATION(0) uniform mediump sampler2D _MainTex;
UNITY_LOCATION(1) uniform mediump sampler2D _FordingTex;
in mediump vec4 vs_COLOR0;
in highp vec2 vs_TEXCOORD0;
in highp vec4 vs_TEXCOORD3;
layout(location = 0) out mediump vec4 SV_Target0;
mediump vec4 u_xlat16_0;
bool u_xlatb0;
mediump vec4 u_xlat16_1;
vec4 u_xlat2;
mediump vec4 u_xlat16_2;
bool u_xlatb2;
mediump vec3 u_xlat16_3;
float u_xlat6;
float u_xlat10;
float u_xlat12;
bool u_xlatb12;
void main()
{
    u_xlat16_0 = texture(_MainTex, vs_TEXCOORD0.xy, _GlobalMipBias.x);
    u_xlat16_1.w = u_xlat16_0.w * vs_COLOR0.w;
    u_xlatb12 = vs_COLOR0.w==0.0;
    if(u_xlatb12){
        SV_Target0.xyz = u_xlat16_0.xyz * u_xlat16_1.www;
        SV_Target0.w = u_xlat16_1.w;
        return;
    }
    u_xlatb12 = 0.0<vs_COLOR0.z;
    if(u_xlatb12){
        u_xlat12 = vs_TEXCOORD3.w * _FordingScale + _FordingOffset;
        u_xlat2.x = 0.0;
        u_xlat2.y = _Time.y * _FordingParam.y;
        u_xlat2.xy = vs_TEXCOORD3.xy * _FordingParam.xx + u_xlat2.xy;
        u_xlat16_2.x = texture(_FordingTex, u_xlat2.xy, _GlobalMipBias.x).x;
        u_xlat16_3.x = u_xlat16_2.x * 2.0 + -1.0;
        u_xlat2.x = u_xlat16_3.x * _FordingParam.z + _FordingLevel;
        u_xlat6 = (-u_xlat12) + u_xlat2.x;
        u_xlat6 = u_xlat6 / u_xlat2.x;
        u_xlat6 = clamp(u_xlat6, 0.0, 1.0);
        u_xlat16_3.xyz = vec3(_DeepColor.x, _DeepColor.y, _DeepColor.z) + (-_ShallowColor.xyz);
        u_xlat16_3.xyz = vec3(u_xlat6) * u_xlat16_3.xyz + _ShallowColor.xyz;
        u_xlat16_3.xyz = (-u_xlat16_0.xyz) + u_xlat16_3.xyz;
        u_xlat16_3.xyz = vec3(u_xlat6) * u_xlat16_3.xyz + u_xlat16_0.xyz;
        u_xlatb12 = u_xlat2.x>=u_xlat12;
        u_xlat12 = u_xlatb12 ? 1.0 : float(0.0);
        u_xlatb2 = _FordingParam.w>=u_xlat6;
        u_xlat2.x = u_xlatb2 ? 1.0 : float(0.0);
        u_xlat12 = u_xlat12 * u_xlat2.x;
        u_xlat2.x = float(1.0) / _FordingParam.w;
        u_xlat2.x = u_xlat2.x * u_xlat6;
        u_xlat2.x = clamp(u_xlat2.x, 0.0, 1.0);
        u_xlat10 = u_xlat2.x * -2.0 + 3.0;
        u_xlat2.x = u_xlat2.x * u_xlat2.x;
        u_xlat2.x = u_xlat2.x * u_xlat10;
        u_xlat12 = u_xlat12 * u_xlat2.x;
        u_xlat2.xzw = vec3(u_xlat12) * _EdgeColor.xyz + u_xlat16_3.xyz;
        u_xlat16_3.x = (-u_xlat6) + 1.0;
        u_xlat16_1.w = u_xlat16_1.w * u_xlat16_3.x;
        u_xlat16_2.xzw = u_xlat2.xzw;
    } else {
        u_xlat16_2.xzw = u_xlat16_0.xyz;
    }
    u_xlat16_3.x = u_xlat16_1.w + -0.00999999978;
    u_xlatb0 = u_xlat16_3.x<0.0;
    if(u_xlatb0){discard;}
    u_xlat16_1.xyz = u_xlat16_1.www * u_xlat16_2.xzw;
    SV_Target0 = u_xlat16_1;
    return;
}

#endif

